// One file of the page's old chats, with no customer name, id, phone, email or link (plan v2 م6 step 87).
const PAGE_IDS = ["110250908003364"]; // المهدوي للعبايات
const hide = (t) => String(t || "")
  .replace(/https?:\/\/\S+|www\.\S+/gi, "[رابط]")
  .replace(/[\w.+-]+@[\w-]+\.[\w.]+/g, "[إيميل]")
  .replace(/(?:\+|00)?[0-9٠-٩][0-9٠-٩\s\-]{6,}[0-9٠-٩]/g, "[رقم]");
const chats = [];
for (const page of $input.all()) {
  for (const c of (page.json.data || [])) {
    const msgs = ((c.messages && c.messages.data) || [])
      .filter((m) => m.message)
      .map((m) => ({
        who: m.from && PAGE_IDS.includes(String(m.from.id)) ? "page" : "customer",
        text: hide(m.message),
        day: String(m.created_time || "").slice(0, 10),
      }))
      .reverse(); // Meta sends newest first
    if (msgs.length) chats.push({ n: chats.length + 1, messages: msgs });
  }
}
const all = chats.flatMap((c) => c.messages);
return [{ json: {
  page: "PAGE_02",
  chats: chats.length,
  messages: all.length,
  from_customers: all.filter((m) => m.who === "customer").length,
  from_page: all.filter((m) => m.who === "page").length,
  note: "no names, ids, phones, emails or links; at most the last 20 messages of each chat (Meta's limit)",
  conversations: chats,
} }];
